const broker = new Broker({ pub: redis }); // sub derived via redis.duplicate()

// Typed subscribe — returns an unsubscribe fn
const unsub = broker.subscribe<Booking>('bookings:org:42', (b) => {
  render(b);
});

// Fire-and-forget — never throws, never blocks the write path
