unsub(); // last listener leaving tears down the Redis subscription

// bookings.broker.ts — the whole file
const ch = (orgId: string) => `bookings:org:${orgId}`;

export const subscribeToOrgBookings = (orgId: string, cb: (b: Booking) => void) =>
  broker.subscribe<Booking>(ch(orgId), cb);

export const publishBookingChange = (b: Booking) =>
  broker.publish(ch(b.organisation_id), b);

import { Broker, HoundApp } from 'hound/';

const broker = new Broker({ pub: redis });

const app = new HoundApp({
  db: redis,
  broker, // job-finished events now cross process boundaries
});

import { Broker, InMemoryStorage } from 'hound/';

const db = new InMemoryStorage();
const broker = new Broker({ pub: db });

const got: unknown[] = [];
broker.subscribe('ch', (p) => got.push(p));
broker.publish('ch', { hello: 'world' });
